+            id: "email-address",
+            name: "email",
+            label: "Email address",
+            type: "email",
+            autocomplete: "email",
+            required: true,
+          },
+          phone: {
+            id: "phone-number",
+            name: "phone",
+            label: "Phone number",
+            type: "tel",
+            autocomplete: "tel",
+            required: false,
+            helpText: "Format: +1 555 123 4567 or 555-123-4567.",
+          },
+        };
+
+        function createEl(tag, attrs = {}, children = []) {
+          const el = document.createElement(tag);
+          for (const [key, value] of Object.entries(attrs)) {
