+          if (!email) {
+            errors.email = "Email address is required.";
+          } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
+            errors.email = "Enter a valid email address.";
+          }
+          return errors;
+        }
+
+        function createField(field) {
+          const wrapper = createEl("div", { className: "form-field" });
+          const label = createEl("label", { for: field.id }, [
+            field.label,
+            field.required
+              ? createEl("span", {
