        color-scheme: dark;
        --bg: #0b1020;
        --bg-elevated: #121a33;
        --bg-soft: #18213f;
        --border: #2c3b68;
        --text: #f4f7ff;
        --muted: #b8c3e6;
        --accent: #86a8ff;
        --accent-strong: #b7c8ff;
        --danger: #ff8e8e;
        --success: #8fe3b4;
        --ring: #c1d0ff;
        --shadow: 0 22px 60px rgba(0, 0, 0, 0.38);
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(134, 168, 255, 0.18), transparent 38%),
          linear-gradient(180deg, #0a1020 0%, #090d19 100%);
      }

      a {
        color: inherit;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        transform: translateY(-200%);
        padding: 0.75rem 1rem;
        border-radius: 0.75rem;
        background: var(--accent-strong);
        color: #10172b;
        font-weight: 700;
        text-decoration: none;
        z-index: 10;
      }

      .skip-link:focus-visible {
        transform: translateY(0);
        outline: 3px solid var(--ring);
        outline-offset: 3px;
      }

      .page {
        width: min(100%, 72rem);
        margin: 0 auto;
        padding: 2rem 1rem 3rem;
      }

      .support-shell {
        background: linear-gradient(180deg, rgba(18, 26, 51, 0.98), rgba(10, 15, 30, 0.98));
        border: 1px solid rgba(134, 168, 255, 0.14);
        border-radius: 1.5rem;
        box-shadow: var(--shadow);
        padding: clamp(1.25rem, 3vw, 2.5rem);
      }

      .eyebrow {
        margin: 0 0 0.25rem;
        color: var(--accent-strong);
        text-transform: uppercase;
        letter-spacing: 0.12em;
        font-size: 0.78rem;
        font-weight: 700;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3.2rem);
        line-height: 1.1;
      }

      .lede {
        max-width: 48rem;
        margin: 0.85rem 0 0;
        color: var(--muted);
        font-size: 1.03rem;
      }

      .form-panel {
        margin-top: 1.75rem;
        padding: clamp(1rem, 2.5vw, 1.5rem);
        border-radius: 1.25rem;
        background: rgba(11, 16, 32, 0.72);
        border: 1px solid rgba(134, 168, 255, 0.12);
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
      }

      label {
        font-weight: 650;
        color: var(--text);
      }

      .required-marker {
        color: var(--accent-strong);
      }

      .field-help,
      .field-error,
      .form-status {
        margin: 0;
        font-size: 0.94rem;
      }

      .field-help {
        color: var(--muted);
      }

      .field-error {
        color: var(--danger);
      }

      .form-status {
        min-height: 1.5em;
        color: var(--success);
      }

      .form-status[data-variant="error"] {
        color: var(--danger);
      }

      input {
        width: 100%;
        min-height: 3rem;
        border: 1px solid var(--border);
        border-radius: 0.9rem;
        padding: 0.8rem 1rem;
        color: var(--text);
        background: rgba(24, 33, 63, 0.95);
        font: inherit;
        transition: border-color 120ms ease, box-shadow 120ms ease, background-color 120ms ease;
      }

      input::placeholder {
        color: #90a0cf;
      }

      input:hover {
        border-color: #49619f;
      }

      input:focus-visible {
        outline: 3px solid var(--ring);
        outline-offset: 2px;
        border-color: transparent;
        box-shadow: 0 0 0 4px rgba(134, 168, 255, 0.16);
      }

      input[aria-invalid="true"] {
        border-color: rgba(255, 142, 142, 0.9);
        box-shadow: 0 0 0 1px rgba(255, 142, 142, 0.25);
      }

      .actions {
        margin-top: 0.35rem;
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        align-items: center;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 0.9rem;
        padding: 0.9rem 1.25rem;
        background: linear-gradient(180deg, #9cb4ff 0%, #6f8ef0 100%);
        color: #10162a;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        box-shadow: 0 12px 24px rgba(111, 142, 240, 0.28);
      }

      button:hover {
        filter: brightness(1.05);
      }

      button:focus-visible {
        outline: 3px solid var(--ring);
        outline-offset: 3px;
      }

      .hint {
        color: var(--muted);
        font-size: 0.95rem;
        margin: 0;
      }

      @media (min-width: 42rem) {
        .form-grid {
          display: grid;
          grid-template-columns: repeat(2, minmax(0, 1fr));
          gap: 1rem;
        }

        .span-2 {
          grid-column: 1 / -1;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --bg-elevated: Canvas;
          --bg-soft: Canvas;
          --border: CanvasText;
          --text: CanvasText;
          --muted: CanvasText;
          --accent: LinkText;
          --accent-strong: LinkText;
          --danger: Mark;
          --success: CanvasText;
          --ring: Highlight;
          --shadow: none;
        }

        .support-shell,
        .form-panel,
        input,
        button {
          forced-color-adjust: auto;
        }

        input,
        button {
          border: 1px solid CanvasText;
        }
      }
    </style>
