            errors.email = "Enter a valid email address.";
          }
          return errors;
        }

        function createField(field) {
          const wrapper = createEl("div", { className: "form-field" });
          const label = createEl("label", { for: field.id }, [
            field.label,
            field.required
              ? createEl("span", {
                  className: "required-marker",
                  textContent: " *",
                  "aria-hidden": "true",
                })
              : null,
          ]);
          const input = createEl("input", {
            id: field.id,
            name: field.name,
            type: field.type,
            autocomplete: field.autocomplete,
            required: field.required || null,
            value: state.values[field.name],
          });
          const help = field.helpText
            ? createEl("p", {
                id: `${field.id}-help`,
                className: "field-help",
                textContent: field.helpText,
              })
            : null;
          const error = createEl("p", {
            id: `${field.id}-error`,
            className: "field-error",
            hidden: true,
            textContent: "",
          });

          wrapper.append(label, input);
          if (help) wrapper.append(help);
          wrapper.append(error);
          return { wrapper, input, error, help };
        }

        function ContactForm() {
          const form = createEl("form", {
            novalidate: true,
            "aria-describedby": "form-status",
          });

          const grid = createEl("div", { className: "form-grid" });
          const fullName = createField(fields.fullName);
          const email = createField(fields.email);
          const phone = createField(fields.phone);
          fullName.wrapper.classList.add("span-2");
          email.wrapper.classList.add("span-2");
          phone.wrapper.classList.add("span-2");

          const status = createEl("p", {
            id: "form-status",
            className: "form-status",
            role: "status",
            "aria-live": "polite",
            "aria-atomic": "true",
            hidden: true,
          });

          const actions = createEl("div", { className: "actions span-2" }, [
            createEl("button", { type: "submit", textContent: "Send message" }),
          ]);

          grid.append(fullName.wrapper, email.wrapper, phone.wrapper);
          form.append(grid, actions, status);

          const refs = { fullName, email, phone, status, form };

          for (const { input } of [fullName, email, phone]) {
            input.addEventListener("input", (event) => {
              state.values[event.target.name] = event.target.value;
              if (state.submitted) {
                state.errors = validate(state.values);
                if (Object.keys(state.errors).length) {
                  state.status = "Review the highlighted fields.";
                  state.statusVariant = "error";
                } else {
                  state.status = "";
                }
              }
              syncForm(refs);
            });
          }

          form.addEventListener("submit", (event) => {
            event.preventDefault();
            state.submitted = true;
            state.errors = validate(state.values);

            if (Object.keys(state.errors).length) {
              state.status = "Please fix the highlighted fields.";
              state.statusVariant = "error";
              syncForm(refs);
              const firstInvalid = Object.keys(state.errors)[0];
              requestAnimationFrame(() => {
                document.getElementById(fields[firstInvalid].id)?.focus();
              });
              return;
            }

            state.status = "Message ready to send.";
            state.statusVariant = "success";
            state.values = { fullName: "", email: "", phone: "" };
            state.errors = {};
            state.submitted = false;
            syncForm(refs);
          });

          syncForm(refs);
          return form;
        }

        function syncField(ref, field) {
          const { input, error } = ref;
          const value = state.values[field.name];
          const message = state.errors[field.name] || "";

          input.value = value;
          if (message) {
            input.setAttribute("aria-invalid", "true");
            const describedBy = [field.helpText ? `${field.id}-help` : null, `${field.id}-error`]
              .filter(Boolean)
              .join(" ");
            input.setAttribute("aria-describedby", describedBy);
            error.textContent = message;
            error.hidden = false;
          } else {
            input.removeAttribute("aria-invalid");
            if (field.helpText) {
              input.setAttribute("aria-describedby", `${field.id}-help`);
            } else {
              input.removeAttribute("aria-describedby");
            }
            error.hidden = true;
            error.textContent = "";
          }
        }

        function syncForm(refs) {
          syncField(refs.fullName, fields.fullName);
          syncField(refs.email, fields.email);
          syncField(refs.phone, fields.phone);

          refs.status.textContent = state.status;
          refs.status.hidden = !state.status;
          refs.status.dataset.variant = state.statusVariant;
          refs.status.setAttribute("data-variant", state.statusVariant);
        }

        app.append(ContactForm());
      })();
    </script>
